import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public class Solution {
    record Valor(String conteudo, long versao) {}

    interface Replica {
        void escrever(String chave, Valor valor);
        Valor ler(String chave);
        boolean disponivel();
    }

    static class QuorumStore {
        private final List<Replica> replicas;
        private final int escrita;
        private final int leitura;
        private final Map<String, Long> versoes = new HashMap<>();

        QuorumStore(List<Replica> replicas, int escrita, int leitura) {
            if (replicas == null || replicas.isEmpty()) {
                throw new IllegalArgumentException("replicas obrigatorias");
            }
            this.replicas = List.copyOf(replicas);
            int n = this.replicas.size();
            if (escrita < 1 || leitura < 1 || escrita > n || leitura > n) {
                throw new IllegalArgumentException("quorum fora dos limites");
            }
            if (escrita + leitura <= n) {
                throw new IllegalArgumentException("R + W precisa ser maior que N");
            }
            this.escrita = escrita;
            this.leitura = leitura;
        }

        boolean put(String chave, String conteudo) {
            exigirChave(chave);
            if (conteudo == null) throw new IllegalArgumentException("conteudo obrigatorio");

            long versao = versoes.merge(chave, 1L, Long::sum);
            var valor = new Valor(conteudo, versao);
            int acks = 0;
            for (var replica : replicas) {
                if (!disponivel(replica)) continue;
                try {
                    replica.escrever(chave, valor);
                    acks++;
                    if (acks >= escrita) return true;
                } catch (RuntimeException ignored) {
                    // conta como falha e tenta a proxima
                }
            }
            return false;
        }

        Optional<String> get(String chave) {
            exigirChave(chave);
            int respostas = 0;
            Valor melhor = null;
            for (var replica : replicas) {
                if (!disponivel(replica)) continue;
                try {
                    Valor lido = replica.ler(chave);
                    respostas++;
                    if (lido != null && (melhor == null || lido.versao() > melhor.versao())) {
                        melhor = lido;
                    }
                    if (respostas >= leitura) break;
                } catch (RuntimeException ignored) {
                    // replica indisponivel na pratica
                }
            }
            if (respostas < leitura || melhor == null) return Optional.empty();
            return Optional.of(melhor.conteudo());
        }

        private boolean disponivel(Replica replica) {
            try {
                return replica.disponivel();
            } catch (RuntimeException e) {
                return false;
            }
        }

        private void exigirChave(String chave) {
            if (chave == null || chave.isBlank()) {
                throw new IllegalArgumentException("chave obrigatoria");
            }
        }
    }
}

