import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class SolutionTest {
    static class ReplicaFake implements Solution.Replica {
        final Map<String, Solution.Valor> dados = new HashMap<>();
        boolean noAr = true;
        boolean falharEscrita = false;

        public void escrever(String chave, Solution.Valor valor) {
            if (!noAr || falharEscrita) throw new IllegalStateException("fora do ar");
            dados.put(chave, valor);
        }

        public Solution.Valor ler(String chave) {
            if (!noAr) throw new IllegalStateException("fora do ar");
            return dados.get(chave);
        }

        public boolean disponivel() { return noAr; }
    }

    private List<ReplicaFake> tresReplicas() {
        return new ArrayList<>(List.of(new ReplicaFake(), new ReplicaFake(), new ReplicaFake()));
    }

    @Test void escritaELeituraComQuorum() {
        var replicas = tresReplicas();
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        assertTrue(store.put("k", "v1"));
        assertEquals("v1", store.get("k").orElseThrow());
        assertEquals(1, replicas.get(0).dados.get("k").versao());
        assertEquals(1, replicas.get(1).dados.get("k").versao());
    }

    @Test void toleraUmaFalha() {
        var replicas = tresReplicas();
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        replicas.get(2).noAr = false;
        assertTrue(store.put("k", "v1"));
        assertEquals("v1", store.get("k").orElseThrow());
    }

    @Test void semQuorumDeEscritaRetornaFalse() {
        var replicas = tresReplicas();
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        replicas.get(1).noAr = false;
        replicas.get(2).noAr = false;
        assertFalse(store.put("k", "v1"));
    }

    @Test void semQuorumDeLeituraRetornaVazio() {
        var replicas = tresReplicas();
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        assertTrue(store.put("k", "v1"));
        replicas.get(1).noAr = false;
        replicas.get(2).noAr = false;
        assertTrue(store.get("k").isEmpty());
    }

    @Test void maiorVersaoVence() {
        var replicas = tresReplicas();
        replicas.get(0).dados.put("k", new Solution.Valor("antigo", 1));
        replicas.get(1).dados.put("k", new Solution.Valor("novo", 2));
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        assertEquals("novo", store.get("k").orElseThrow());
    }

    @Test void versaoIncrementaPorChave() {
        var replicas = tresReplicas();
        var store = new Solution.QuorumStore(new ArrayList<>(replicas), 2, 2);
        store.put("k", "v1");
        store.put("k", "v2");
        assertEquals(2, replicas.get(0).dados.get("k").versao());
        assertEquals("v2", store.get("k").orElseThrow());
    }

    @Test void configuracaoInvalida() {
        var replicas = tresReplicas();
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.QuorumStore(new ArrayList<>(replicas), 1, 2));
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.QuorumStore(new ArrayList<>(replicas), 0, 3));
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.QuorumStore(new ArrayList<>(), 1, 1));
    }

    @Test void chaveOuConteudoInvalidos() {
        var store = new Solution.QuorumStore(new ArrayList<>(tresReplicas()), 2, 2);
        assertThrows(IllegalArgumentException.class, () -> store.put(" ", "v"));
        assertThrows(IllegalArgumentException.class, () -> store.put("k", null));
        assertThrows(IllegalArgumentException.class, () -> store.get(null));
    }
}
